// ─── File: MultiLevelCacheDemo.java ───
// L1 (per-instance Caffeine) in front of L2 (shared Redis) in front of DB.
// On L2 expiry, each instance serves from L1 → only ONE reload per instance.
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.logging.*;

public class MultiLevelCacheDemo {
    private static final Logger log = Logger.getLogger("MLC");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Database db = new Database();
        L2Cache l2 = new L2Cache(db);
        // Two instances, each with its OWN L1 (short 2s TTL) sharing the one L2.
        AppInstance inst1 = new AppInstance("inst-1", new L1Cache(2000), l2);
        AppInstance inst2 = new AppInstance("inst-2", new L1Cache(2000), l2);

        long now = 1_000_000L;
        // Warm both instances' L1 and the shared L2.
        inst1.getRate("SAVINGS", now); inst2.getRate("SAVINGS", now);
        db.resetCount(); l2.resetReloads();

        // L2 key expires; a BURST of reads hits both instances simultaneously.
        log.info("=== L2 expired; burst across 2 instances — L1 absorbs it ===");
        l2.expire("SAVINGS");
        long tBurst = now + 1000;   // still within L1's 2s TTL
        burst(inst1, inst2, "SAVINGS", tBurst, 20);  // 20 requests per instance
        log.info(() -> "During burst within L1 TTL: L2 reloads=" + l2.reloads()
                + ", DB reads=" + db.readCount() + " (served from L1, DB barely touched)");

        // After L1 TTL elapses, each instance falls through ONCE (single-flight).
        log.info("=== L1 TTL elapsed; each instance reloads ONCE (single-flight) ===");
        db.resetCount(); l2.resetReloads();
        long tAfterL1 = now + 3000;   // past L1's 2s TTL
        burst(inst1, inst2, "SAVINGS", tAfterL1, 20);
        log.info(() -> "After L1 TTL: L2 reloads=" + l2.reloads()
                + " (≈ one per instance), NOT one per request");

        // Consistency: broadcast invalidation on a rate change → prompt L1 eviction.
        log.info("=== Rate change → broadcast invalidation evicts L1 on all instances ===");
        db.updateRate("SAVINGS", 400);              // 4.00%
        inst1.onInvalidationBroadcast("SAVINGS");   // pub/sub message
        inst2.onInvalidationBroadcast("SAVINGS");
        log.info(() -> "inst-2 sees new rate promptly: " + inst2.getRate("SAVINGS", now + 4000));
    }

    static void burst(AppInstance a, AppInstance b, String key, long t, int perInstance) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(8);
        List<Future<?>> fs = new ArrayList<>();
        for (int i = 0; i < perInstance; i++) { fs.add(pool.submit(() -> a.getRate(key, t))); fs.add(pool.submit(() -> b.getRate(key, t))); }
        for (Future<?> f : fs) try { f.get(); } catch (ExecutionException ignored) {}
        pool.shutdown();
    }
}

// ─── db/Database.java (source of truth) ───
class Database {
    private final Map<String, Integer> rates = new ConcurrentHashMap<>(Map.of("SAVINGS", 350));
    private final AtomicInteger reads = new AtomicInteger();
    int loadRate(String p) { reads.incrementAndGet(); return rates.get(p); }
    void updateRate(String p, int bps) { rates.put(p, bps); }
    int readCount() { return reads.get(); } void resetCount() { reads.set(0); }
}

// ─── cache/L2Cache.java (shared Redis-style, single-flight to DB) ───
class L2Cache {
    private final Database db; private final Map<String, Integer> store = new ConcurrentHashMap<>();
    private final AtomicInteger reloads = new AtomicInteger();
    L2Cache(Database db) { this.db = db; }
    synchronized Integer get(String key) {   // single-flight: one DB reload across fleet
        Integer v = store.get(key);
        if (v == null) { reloads.incrementAndGet(); v = db.loadRate(key); store.put(key, v); }
        return v;
    }
    void put(String key, int v) { store.put(key, v); }
    void expire(String key) { store.remove(key); }
    int reloads() { return reloads.get(); } void resetReloads() { reloads.set(0); }
}

// ─── cache/L1Cache.java (per-instance Caffeine-style, single-flight, TTL) ───
class L1Cache {
    private final long ttlMs; private final Map<String, long[]> entries = new ConcurrentHashMap<>(); // key→[value,expiry]
    private final Set<String> loading = ConcurrentHashMap.newKeySet();
    L1Cache(long ttlMs) { this.ttlMs = ttlMs; }
    Integer getIfFresh(String key, long now) {
        long[] e = entries.get(key);
        if (e != null && now < e[1]) return (int) e[0];
        return null;
    }
    boolean tryBeginLoad(String key) { return loading.add(key); }  // single-flight winner
    void endLoad(String key) { loading.remove(key); }
    void put(String key, int value, long now) { entries.put(key, new long[]{value, now + ttlMs}); }
    void evict(String key) { entries.remove(key); }
}

// ─── app/AppInstance.java (L1 → L2 → DB read-through) ───
class AppInstance {
    private static final Logger log = Logger.getLogger("MLC");
    private final String name; private final L1Cache l1; private final L2Cache l2;
    AppInstance(String name, L1Cache l1, L2Cache l2) { this.name = name; this.l1 = l1; this.l2 = l2; }
    int getRate(String key, long now) {
        Integer fromL1 = l1.getIfFresh(key, now);
        if (fromL1 != null) return fromL1;              // L1 hit → absorbs the burst
        // L1 miss: single-flight so only ONE request per instance falls through to L2.
        if (l1.tryBeginLoad(key)) {
            try {
                int v = l2.get(key);                    // L2 (shared) → DB only if L2 missed
                l1.put(key, v, now);
                return v;
            } finally { l1.endLoad(key); }
        }
        // Another thread on this instance is loading; serve last known or L2 directly.
        Integer again = l1.getIfFresh(key, now);
        return again != null ? again : l2.get(key);
    }
    void onInvalidationBroadcast(String key) { l1.evict(key); }   // pub/sub → prompt eviction
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
